import { computed, inject, onBeforeUnmount, ref, watch } from 'vue'
import { TreeContextKey, type TreeNode, type TreeNodeSlotProps } from './types'

const props = defineProps<{
  node: TreeNode
  parent: TreeNode | null
  level: number
  index: number
  setSize: number
}>()

